// Get the 4D hyperplane equation from the cell
HyperPlane hp = rt.hyperplane(c);

// Extract the coefficients (a, b, c, d) from the hyperplane equation: ax + by + cz + dw = e
double a = hp.a();
double b = hp.b();
double c = hp.c();
double d = hp.d();
double e = hp.e();

// The velocity is the gradient of the potential in 3D space
// In lifted space, the velocity is the projection of the hyperplane normal onto 3D space
// The normal vector in 4D is (a, b, c, d), and we want the 3D component (a, b, c)
// The velocity is then normalized by the time parameter and the w-component (d)
double norm = std::sqrt(a*a + b*b + c*c);
if (norm < 1e-10) {
    return Vector(0.0, 0.0, 0.0);
}

double w_component = d;
double velocity_scale = 2.0 * time / w_component;

return Vector(a * velocity_scale / norm,
              b * velocity_scale / norm,
              c * velocity_scale / norm);

